import sys


def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    X = [int(x) for x in data[1 : N + 1]]
    Y = [int(x) for x in data[N + 1 : 2 * N + 1]]

    U = [x + y for x, y in zip(X, Y)]
    V = [x - y for x, y in zip(X, Y)]

    u_min = min(U)
    u_max = max(U)
    v_min = min(V)
    v_max = max(V)

    # Se todos os pontos já cabem em um único quadrado
    total_span = max(u_max - u_min, v_max - v_min)
    if total_span == 0:
        print(0)
        return

    def can(D):
        if total_span <= D:
            return True

        # Teste 1: Q1 no canto inferior esquerdo
        # Q1 = [u_min, u_min + D] x [v_min, v_min + D]
        u_lim1 = u_min + D
        v_lim1 = v_min + D
        min_u = float("inf")
        max_u = float("-inf")
        min_v = float("inf")
        max_v = float("-inf")
        valid1 = True

        for u, v in zip(U, V):
            if u > u_lim1 or v > v_lim1:
                if u < min_u:
                    min_u = u
                if u > max_u:
                    max_u = u
                if v < min_v:
                    min_v = v
                if v > max_v:
                    max_v = v

        if min_u == float("inf") or (
            max_u - min_u <= D and max_v - min_v <= D
        ):
            return True

        # Teste 2: Q1 no canto superior esquerdo
        # Q1 = [u_min, u_min + D] x [v_max - D, v_max]
        u_lim2 = u_min + D
        v_lim2 = v_max - D
        min_u = float("inf")
        max_u = float("-inf")
        min_v = float("inf")
        max_v = float("-inf")

        for u, v in zip(U, V):
            if u > u_lim2 or v < v_lim2:
                if u < min_u:
                    min_u = u
                if u > max_u:
                    max_u = u
                if v < min_v:
                    min_v = v
                if v > max_v:
                    max_v = v

        if min_u == float("inf") or (
            max_u - min_u <= D and max_v - min_v <= D
        ):
            return True

        return False

    low = 0
    high = total_span
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if can(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    print(ans)


if __name__ == "__main__":
    solve()
